#!/usr/bin/env bash
set -euo pipefail

# run-u-end-to-end.sh TARGET QUERIES OUT [--drop-opcode OP] [--allow-unanswerable N]
#
# U side: the queries were generated by the oracle from the *upstream* rules
# (`oracle/scripts/gen-u.sh`), not by gisel.  Both implementations answer the
# same file: the official runner from the pinned library, ours from the
# generated include.  This is the direction that proves gisel does not miss an
# upstream rule.
#
#   TARGET   x86 | aarch64 | riscv | arm | mips | ppc | m68k | wasm | spirv
#   QUERIES  queries.jsonl from gen-u.sh
#   OUT      artifacts (runners, answers, diff.json, attribution.json)
#
# Environment:
#   AB_TREE / AB_BUILD   pinned checkout and build (defaults below)
#   U_INC                generated include; if unset it is built from the
#                        corpus with `gisel gen --emit=inc`
#
# --drop-opcode OP runs the negative control: OP's rules are replaced with
# `.unsupported()` in the include, and the run passes only if the diff sees
# disagreements and every one of them is attributed to that builder's rulesets.
#
# --allow-ref-asserts pins the queries where the *reference* asserts before
# answering and ours answers (diff.py's `ref_asserted` class).  They are
# upstream defects in the query's own type, not a rule translation gap.
# `N` pins the total; `file:line=count,...` or `@file.json` pins each assert
# site, so a new assert class cannot hide behind an unchanged total.
TARGET=${1:?usage: run-u-end-to-end.sh TARGET QUERIES OUT [--drop-opcode OP]}
QUERIES=${2:?}
OUT=${3:?}
shift 3
DROP=""
ALLOW_UNANSWERABLE=0
ALLOW_REF_ASSERTS=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --drop-opcode) DROP=${2:?}; shift 2 ;;
    --allow-unanswerable) ALLOW_UNANSWERABLE=${2:?}; shift 2 ;;
    --allow-ref-asserts) ALLOW_REF_ASSERTS=${2:?}; shift 2 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

. "$(cd "$(dirname "$0")" && pwd)/env.sh"
TREE=${AB_TREE:-/home/ubuntu/llvm/trees/explore}
BUILD=${AB_BUILD:-/home/ubuntu/llvm/builds/explore}
mkdir -p "$OUT"

case "$TARGET" in
  x86)     BUILDER=$ROOT/build-x86-ctor-runner.sh
           CORPUS=$GISEL/tests/corpus/X86LegalizerInfo.gisel
           INC_NAME=X86LegalizerInfo.inc ;;
  aarch64) BUILDER=$ROOT/build-aarch64-runner.sh
           CORPUS=$GISEL/tests/corpus/AArch64LegalizerInfo.gisel
           INC_NAME=AArch64LegalizerInfo.inc ;;
  riscv)   BUILDER=$ROOT/build-riscv-runner.sh
           CORPUS=$GISEL/tests/corpus/RISCVLegalizerInfo.gisel
           INC_NAME=RISCVLegalizerInfo.inc ;;
  arm)     BUILDER=$ROOT/build-arm-runner.sh
           CORPUS=$GISEL/tests/corpus/ARMLegalizerInfo.gisel
           INC_NAME=ARMLegalizerInfo.inc ;;
  mips)    BUILDER=$ROOT/build-mips-runner.sh
           CORPUS=$GISEL/tests/corpus/MipsLegalizerInfo.gisel
           INC_NAME=MipsLegalizerInfo.inc ;;
  ppc)     BUILDER=$ROOT/build-ppc-runner.sh
           CORPUS=$GISEL/tests/corpus/PowerPCLegalizerInfo.gisel
           INC_NAME=PowerPCLegalizerInfo.inc ;;
  m68k)    BUILDER=$ROOT/build-m68k-runner.sh
           CORPUS=$GISEL/tests/corpus/M68kLegalizerInfo.gisel
           INC_NAME=M68kLegalizerInfo.inc ;;
  wasm)    BUILDER=$ROOT/build-wasm-runner.sh
           CORPUS=$GISEL/tests/corpus/WebAssemblyLegalizerInfo.gisel
           INC_NAME=WebAssemblyLegalizerInfo.inc ;;
  spirv)   BUILDER=$ROOT/build-spirv-runner.sh
           CORPUS=$GISEL/tests/corpus/SPIRVLegalizerInfo.gisel
           INC_NAME=SPIRVLegalizerInfo.inc ;;
  *) echo "unsupported target: $TARGET" >&2; exit 2 ;;
esac

test -f "$QUERIES"

if [[ -n ${U_INC:-} ]]; then
  BASE_INC=$U_INC
else
  BASE_INC=$OUT/$INC_NAME
  python3 -m gisel gen "$CORPUS" --emit=inc --out "$BASE_INC" >/dev/null
fi
test -f "$BASE_INC"

OURS_INC=$BASE_INC
EXPECT=""
if [[ -n $DROP ]]; then
  OURS_INC=$OUT/$INC_NAME.injected
  EXPECT=$OUT/expected-rulesets.json
  python3 "$ROOT/inject-missing-opcode.py" "$BASE_INC" "$DROP" \
    "$OURS_INC" --expect "$EXPECT" >/dev/null
fi

echo "[1/4] build runners ($TARGET${DROP:+, drop $DROP})" >&2
"$BUILDER" "$TREE" "$BUILD" "$OURS_INC" "$OUT/runner"

echo "[2/4] answer: official" >&2
python3 "$ROOT/run-queries.py" "$OUT/runner.official" "$QUERIES" \
  "$OUT/official.answers.jsonl"

echo "[3/4] answer: ours" >&2
python3 "$ROOT/run-queries.py" "$OUT/runner.ours" "$QUERIES" \
  "$OUT/ours.answers.jsonl"

echo "[4/4] diff + attribution" >&2
set +e
DIFF_ARGS=(--json --details 200000)
if [[ -n $ALLOW_REF_ASSERTS ]]; then
  DIFF_ARGS+=(--allow-ref-asserts "$ALLOW_REF_ASSERTS")
fi
python3 "$ROOT/diff.py" "$OUT/official.answers.jsonl" \
  "$OUT/ours.answers.jsonl" "${DIFF_ARGS[@]}" > "$OUT/diff.json"
DIFF_RC=$?
set -e

python3 "$ROOT/u-attribution.py" --diff "$OUT/diff.json" \
  --queries "$QUERIES" --json ${EXPECT:+--expect "$EXPECT"} \
  | tee "$OUT/attribution.json"

UNANS=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['unanswerable'])" "$OUT/diff.json")
echo "diff_rc=$DIFF_RC unanswerable=$UNANS" >&2

if [[ -n $DROP ]]; then
  # The control passes only when the diff *does* disagree and the attribution
  # blamed the injected builder; u-attribution.py already enforced both.
  if [[ $DIFF_RC -eq 0 ]]; then
    echo "negative control: diff agreed, injection was not observed" >&2
    exit 1
  fi
  exit 0
fi

if [[ $DIFF_RC -ne 0 ]]; then
  echo "U side disagrees (see $OUT/diff.json)" >&2
  exit 1
fi
if [[ "$UNANS" -gt "$ALLOW_UNANSWERABLE" ]]; then
  echo "$UNANS queries unanswerable, allowed $ALLOW_UNANSWERABLE" >&2
  exit 1
fi
